from pathlib import Path
import json,base64,shutil
root=Path(__file__).resolve().parent
site=root/'design/site'
def js(value):return json.dumps(value,ensure_ascii=False).replace('</','<\\/')
pages={p.name:p.read_text() for p in sorted(site.glob('*.html'))}
assets={'imagens/'+p.name:'data:'+('image/png' if p.suffix=='.png' else 'image/jpeg')+';base64,'+base64.b64encode(p.read_bytes()).decode() for p in (site/'imagens').iterdir() if p.is_file()}
content='''<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monte Casa Branca · Design V1</title><style>*{box-sizing:border-box}body{margin:0;background:#e7dfd3;color:#49362e;font:14px/1.5 Arial,sans-serif}.review-header{background:#f7f4ed;padding:15px 24px;border-bottom:1px solid #d2c6b6;display:flex;gap:20px;align-items:center;flex-wrap:wrap}.review-header strong{font:400 22px Georgia,serif;margin-right:auto}.review-header label{display:flex;align-items:center;gap:10px;font-size:12px}.review-header select,.review-header button{font:inherit;background:transparent;border:1px solid #cbb8a4;border-radius:4px;min-height:40px;padding:8px 14px;color:#49362e}.review-header button{cursor:pointer}.review-header button[aria-pressed=true]{background:#a75532;color:white;border-color:#a75532}.review-note{margin:0;padding:10px 24px;background:#f7f4ed;color:#7b7267;font-size:11px}#review-stage{padding:20px;overflow:hidden}#review-slot{position:relative;margin:auto;overflow:hidden;box-shadow:0 4px 35px #49362e20}iframe{display:block;border:0;background:#f7f4ed;transform-origin:top left}:focus-visible{outline:2px solid #a75532;outline-offset:3px}@media(max-width:650px){.review-header{padding:12px 15px;gap:10px}.review-header strong{width:100%;font-size:20px}.review-header label{flex:1}.review-header select{min-width:0;width:100%;max-width:190px}.review-header button{padding:7px 12px}#review-stage{padding:10px}.review-note{padding:10px 15px}}</style></head><body><div class="review-header"><strong>Monte Casa Branca · Design V1</strong><label>Página <select id="review-page" aria-label="Página a visualizar"><option value="index.html">Início</option><option value="a-casa.html">A casa</option><option value="fotografias.html">Fotografias</option><option value="precos.html">Preços e datas</option><option value="localizacao.html">Localização</option><option value="perguntas.html">Perguntas</option><option value="contactos.html">Contactos</option></select></label><button id="review-pc" aria-pressed="true">PC · 1280</button><button id="review-mobile" aria-pressed="false">Mobile · 390</button></div><p class="review-note">Sete páginas navegáveis · estudo de design para apreciação · texto provisório · calendário e meteorologia de exemplo. A apresentação abre num único ficheiro.</p><div id="review-stage"><div id="review-slot"><iframe id="review-frame" title="Página do site Monte Casa Branca" width="1280" height="1000"></iframe></div></div><script>
const PAGES=__PAGES__,ASSETS=__ASSETS__,STYLE=__STYLE__,INTERACTION=__INTERACTION__,DATA=__DATA__,KIT=__KIT__,BASESTYLE=__BASESTYLE__;
const frame=document.querySelector('#review-frame'),picker=document.querySelector('#review-page');let mode=matchMedia('(max-width:650px)').matches?'mobile':'pc',page='index.html',anchor='';
const script=s=>'<scr'+'ipt>'+s+'</scr'+'ipt>';
function fit(){let w=mode==='mobile'?390:1280;let scale=Math.min(1,(document.querySelector('#review-stage').clientWidth-24)/w);frame.width=w;frame.height=1000;frame.style.transform='scale('+scale+')';document.querySelector('#review-slot').style.width=(w*scale)+'px';document.querySelector('#review-slot').style.height=(1000*scale)+'px';document.querySelector('#review-pc').setAttribute('aria-pressed',mode==='pc');document.querySelector('#review-mobile').setAttribute('aria-pressed',mode==='mobile')}
function render(){let s=PAGES[page];for(const [name,data]of Object.entries(ASSETS))s=s.split(name).join(data);s=s.replace('<link rel="stylesheet" href="estilos-site.css">','<style>'+BASESTYLE+'\\n'+STYLE+'</style>').replace('<script src="apresentacao.js" defer></scr'+'ipt>','');s=s.replace('</bo'+'dy>',script('window.MCB_BASE_CONFIG={tempo:"exemplo",hoje:"2026-10-24"};')+script(DATA)+script(INTERACTION)+script(KIT)+'</bo'+'dy>');frame.srcdoc=s;picker.value=page;fit()}
frame.onload=()=>{if(anchor){frame.contentWindow.location.hash=anchor;const el=frame.contentDocument.getElementById(anchor);el?.scrollIntoView()}frame.contentDocument.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;const href=a.getAttribute('href'),parts=href.split('#');if(PAGES[parts[0]]){e.preventDefault();page=parts[0];anchor=parts[1]||'';render()}else if(href.startsWith('https://')){a.target='_blank';a.rel='noopener'}})};
picker.onchange=()=>{page=picker.value;anchor='';render()};document.querySelector('#review-pc').onclick=()=>{mode='pc';fit()};document.querySelector('#review-mobile').onclick=()=>{mode='mobile';fit()};new ResizeObserver(fit).observe(document.querySelector('#review-stage'));render();
</script></body></html>'''
values={'PAGES':pages,'ASSETS':assets,'STYLE':(site/'estilos-site.css').read_text(),'INTERACTION':(site/'apresentacao.js').read_text(),'DATA':(root/'demo/site/base/dados.js').read_text(),'KIT':(root/'demo/base/kit/base.js').read_text(),'BASESTYLE':(root/'demo/base/kit/base.css').read_text()}
for key,value in values.items():content=content.replace('__'+key+'__',js(value))
out=root/'Monte-Casa-Branca-Design-V1.html';out.write_text(content)
shutil.copy2(out,root/'preview/visualizador.html')
print(out, out.stat().st_size)
